window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-123"]=[{"id":"set2-VL8VtOt2","fingerprint":"b9fda648c0aabf57","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este mecanismul patogenic principal responsabil pentru apariția anodonției?","options":[{"id":"A","text":"Neformarea, lipsa de dezvoltare embrionară sau atrofia mugurilor dentari."},{"id":"B","text":"Tulburări de mineralizare a smalțului și dentinei în timpul odontogenezei."},{"id":"C","text":"Extracția prematură a dinților temporari, care împiedică erupția celor permanenți."},{"id":"D","text":"Pierderea dinților în urma unor traumatisme dento-alveolare."},{"id":"E","text":"Distrugerea coronară masivă a dinților cauzată de procese carioase."}],"correct":["A"],"pages":[460],"source":"set-2"},{"id":"set2-PYLgyrst","fingerprint":"c84d3883cbf0aed1","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următorii termeni sunt utilizați pentru a descrie absența congenitală a dinților?","options":[{"id":"A","text":"Oligodonție"},{"id":"B","text":"Hipodonție"},{"id":"C","text":"Hiperdonție"},{"id":"D","text":"Displazie"},{"id":"E","text":"Agenezie"}],"correct":["A","B","E"],"pages":[460],"source":"set-2"},{"id":"set2-5BEttaOh","fingerprint":"233dcd5a0baf4dd5","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este afirmația corectă privind frecvența anodonției în funcție de sex?","options":[{"id":"A","text":"Este de 16 ori mai frecventă la sexul feminin decât la cel masculin."},{"id":"B","text":"Afectează sexul feminin cu o frecvență aproape dublă (2/1) față de cel masculin."},{"id":"C","text":"Nu există diferențe semnificative de incidență între cele două sexe."},{"id":"D","text":"Este mai frecventă la sexul masculin, la fel ca în cazul dinților supranumerari."},{"id":"E","text":"Afectează sexul masculin cu o frecvență aproape dublă (2/1) față de cel feminin."}],"correct":["B"],"pages":[460],"source":"set-2"},{"id":"set2-KAcDiDfU","fingerprint":"9630780517ecaf0e","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Cum se compară frecvența anodonției între cele două tipuri de dentiții?","options":[{"id":"A","text":"Anodonția este o anomalie exclusivă a dentiției permanente."},{"id":"B","text":"Este de 2 până la 10 ori mai frecventă în dentiția temporară decât în cea permanentă."},{"id":"C","text":"Apare cu o frecvență mult mai mare în dentiția permanentă, cu un raport de 16/1 față de cea temporară."},{"id":"D","text":"Referirile științifice sunt mai numeroase pentru dentiția temporară datorită complexității cazurilor."},{"id":"E","text":"Frecvența este aproximativ egală în dentiția temporară și cea permanentă."}],"correct":["C"],"pages":[460],"source":"set-2"},{"id":"set2--PA9slSY","fingerprint":"7028650ba682c790","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următorii dinți sunt cel mai frecvent afectați de anodonție, conform studiilor statistice?","options":[{"id":"A","text":"Caninii superiori"},{"id":"B","text":"Al doilea premolar inferior"},{"id":"C","text":"Incisivul central inferior"},{"id":"D","text":"Molarii de minte"},{"id":"E","text":"Incisivul lateral superior"}],"correct":["B","C","D","E"],"pages":[460],"source":"set-2"},{"id":"set2-8aIakZfg","fingerprint":"05f73c306bf72f0e","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt caracteristicile epidemiologice ale anodonției?","options":[{"id":"A","text":"Frecvența sa în raport cu alte anomalii dento-maxilare este cuprinsă între 2 și 10%."},{"id":"B","text":"Incidența este mai mare la sexul masculin, similar cu situația dinților supranumerari."},{"id":"C","text":"Afectează dentiția permanentă de 16 ori mai frecvent decât pe cea temporară."},{"id":"D","text":"Referirile științifice la minusul dentar din dentiția temporară sunt foarte bogate."},{"id":"E","text":"Sexul feminin este afectat de aproximativ două ori mai des decât cel masculin."}],"correct":["A","C","E"],"pages":[461],"source":"set-2"},{"id":"set2-ZP8ir5ca","fingerprint":"a6a6872c186b4aa0","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este ordinea corectă, în sens descrescător al frecvenței, a dinților cel mai des afectați de anodonție?","options":[{"id":"A","text":"Al doilea premolar inferior, incisivul lateral superior, molarii de minte, incisivul central inferior."},{"id":"B","text":"Incisivul lateral superior, molarii de minte, al doilea premolar inferior, incisivul central inferior."},{"id":"C","text":"Incisivul central superior, molarul de 6 ani, molarul de 12 ani, premolarul 1 inferior."},{"id":"D","text":"Molarii de minte, incisivul lateral superior, al doilea premolar inferior, incisivul central inferior."},{"id":"E","text":"Molarii de minte, al doilea premolar inferior, incisivul lateral superior, incisivul central superior."}],"correct":["D"],"pages":[461],"source":"set-2"},{"id":"set2-jnLu4td6","fingerprint":"0eeb51e2ccc42ea8","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Conform teoriei proterogenetice descrise de Quinet, care sunt etapele plauzibile ale procesului de dispariție a unui dinte?","options":[{"id":"A","text":"Epuizarea distală a gradientului de molarizare."},{"id":"B","text":"Trecerea de la biradiculație la monoradiculație și reducerea dimensiunii dentare."},{"id":"C","text":"Labilitate volumetrică, morfologică și variabilitate de poziție."},{"id":"D","text":"Creșterea cantității de material embrionar pentru a compensa absența dintelui."},{"id":"E","text":"Încorporarea totală a unui dinte de către un dinte vecin."}],"correct":["B","C","E"],"pages":[461],"source":"set-2"},{"id":"set2-Zgf_-KYA","fingerprint":"eb66adf71be7b6bd","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce dinte reprezintă o excepție de la regula conform căreia modificarea filogenetică a formulei dentare interesează ultimii dinți din fiecare grup?","options":[{"id":"A","text":"Incisivul lateral superior."},{"id":"B","text":"Al doilea premolar inferior."},{"id":"C","text":"Incisivul central inferior."},{"id":"D","text":"Incisivul central superior."},{"id":"E","text":"Molarul de minte."}],"correct":["C"],"pages":[461],"source":"set-2"},{"id":"set2-GpZxTsiv","fingerprint":"31212544527da516","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Potrivit ipotezelor lui Quinet, care este mecanismul principal ce explică agenezia premolarilor 2?","options":[{"id":"A","text":"O zestre enzimatică insuficientă pentru declanșarea fenomenelor de inducție biologică."},{"id":"B","text":"Epuizarea distală a gradientului de molarizare."},{"id":"C","text":"Un proces de trecere de la biradiculație la monoradiculație specific acestui dinte."},{"id":"D","text":"Situarea lor între doi gradienți puternici, de caninizare și de molarizare."},{"id":"E","text":"Acțiunea unui gradient de incisivizare mai slab, dar avantajat de o cantitate micșorată de material embrionar."}],"correct":["D"],"pages":[461],"source":"set-2"},{"id":"set2-am5TqtKb","fingerprint":"4d79d9d254f9955a","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Conform teoriilor ontogenetice, care este contextul în care apare absența dentară multiplă?","options":[{"id":"A","text":"Prin încorporarea totală a mai multor dinți de către dinții vecini, conform teoriei 'sfârșitului de serie'."},{"id":"B","text":"Din cauza reducerii filogenetice a maxilarelor, ca o adaptare la modificarea condițiilor de viață și alimentație."},{"id":"C","text":"Datorită unui material embrionar redus cantitativ a cărui zestre enzimatică este insuficientă."},{"id":"D","text":"Atunci când cauze cu acțiune electivă pe formațiunile ectodermale acționează asupra embrionului în perioada de proliferare a mugurilor dentari."},{"id":"E","text":"Ca urmare a unui proces evolutiv proterogenetic ce merge cert spre reducerea numerică a dinților."}],"correct":["D"],"pages":[461],"source":"set-2"},{"id":"set2-5NK7wG5v","fingerprint":"a2d5fb7ef63cdc3a","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele mecanisme sunt implicate în apariția absenței dentare, conform ipotezelor ontogenetice?","options":[{"id":"A","text":"Insuficiența potențialului evolutiv al componentelor odontogene, ducând la atrofia produsului dentar."},{"id":"B","text":"Stimularea excesivă a potențialului formativ al teritoriilor odontogene, ducând la epuizarea lor."},{"id":"C","text":"Distrugerea germenilor dentari parțial mineralizați prin procese autoimune sistemice."},{"id":"D","text":"Distrugerea lamei dentare și a produselor sale prin acțiune directă în a doua jumătate a sarcinii."},{"id":"E","text":"Insuficiența potențialului formativ al teritoriilor prezumtiv odontogene, legată de lipsa unui inductor primar."}],"correct":["A","D","E"],"pages":[462],"source":"set-2"},{"id":"set2-3d7jgRYO","fingerprint":"107645fd56ee11e7","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În ce perioadă acționează factorii care determină distrugerea lamei dentare și a produselor sale, ducând la anodonție?","options":[{"id":"A","text":"Exclusiv în primii ani de viață, după naștere."},{"id":"B","text":"În a doua jumătate a sarcinii și la naștere."},{"id":"C","text":"În perioada de proliferare a mugurilor dentari din lama dentară, la începutul sarcinii."},{"id":"D","text":"În cursul bolilor eruptive, prin necroza maxilarelor."},{"id":"E","text":"Doar în perioada organogenezei, prin acțiune indirectă."}],"correct":["B"],"pages":[462],"source":"set-2"},{"id":"set2-LfDEn2rT","fingerprint":"254abb1c478a007c","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următorii factori generali sunt incriminați în geneza anodonțiilor?","options":[{"id":"A","text":"Tulburările endocrine și deficiențele nutriționale din timpul sarcinii."},{"id":"B","text":"Procesele supurative periapicale ale dinților temporari."},{"id":"C","text":"Bolile infecto-contagioase ale mamei în timpul sarcinii, precum rubeola."},{"id":"D","text":"Displazia ectodermală sau ecto-mezodermală."},{"id":"E","text":"Extracțiile brutale ale dinților temporari."}],"correct":["A","C","D"],"pages":[462],"source":"set-2"},{"id":"set2-mny7P3nJ","fingerprint":"ef1089cb9bf94cba","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce proces biochimic fundamental este menționat ca fiind inhibat în mecanismul de insuficiență a potențialului evolutiv al componentelor odontogene?","options":[{"id":"A","text":"Metabolismul calciului, ducând la o mineralizare deficitară."},{"id":"B","text":"Sinteza acizilor nucleici, care poate fi afectată de lipsa de oxigen."},{"id":"C","text":"Transportul vitaminelor la nivel celular."},{"id":"D","text":"Producția de factori de creștere de către ectoderm."},{"id":"E","text":"Sinteza colagenului în papila dentară."}],"correct":["B"],"pages":[462],"source":"set-2"},{"id":"set2-T88Th0MT","fingerprint":"8c5b8581d95ee12d","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care dintre următoarele reprezintă un factor local cu potențial etiologic în cazul anodonțiilor?","options":[{"id":"A","text":"Consumul irațional de alcool în timpul sarcinii."},{"id":"B","text":"Osteomielita acută a maxilarelor în timpul formării dinților."},{"id":"C","text":"Virozele contractate de mamă în timpul sarcinii."},{"id":"D","text":"Utilizarea forcepsului la naștere."},{"id":"E","text":"Displazia ecto-mezodermală."}],"correct":["B"],"pages":[462],"source":"set-2"},{"id":"set2-POzrbYH6","fingerprint":"b5cbbd61cc91b981","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt afirmațiile corecte referitoare la factorii cauzali ai anodonțiilor în perioada organogenezei?","options":[{"id":"A","text":"Factorii pot avea o acțiune generală sau locală, directă sau indirectă."},{"id":"B","text":"Acțiunea factorilor este întotdeauna singulară și niciodată sinergică."},{"id":"C","text":"Doar factorii locali pot acționa în această perioadă, prin mecanisme directe."},{"id":"D","text":"Doar factorii generali cu acțiune indirectă sunt implicați în organogeneză."},{"id":"E","text":"Atât factorii generali, cât și cei locali sunt considerați posibili factori cauzali."}],"correct":["A","E"],"pages":[462],"source":"set-2"},{"id":"set2-lpRv67fp","fingerprint":"328ce28e8a76806c","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce tip de distribuție a dinților absenți este asociat cu acțiunea unor cauze asupra embrionului în perioada de proliferare a mugurilor dentari?","options":[{"id":"A","text":"Absența este întotdeauna asociată cu dinți supranumerari în alte zone."},{"id":"B","text":"Absența este simetrică și afectează exclusiv dinții frontali."},{"id":"C","text":"Absența este multiplă și selectiv distribuită, afectând doar un grup dentar."},{"id":"D","text":"Absența este multiplă și neselectiv distribuită."},{"id":"E","text":"Absența este singulară, afectând de obicei un singur dinte."}],"correct":["D"],"pages":[462],"source":"set-2"},{"id":"set2-RMVz2dtn","fingerprint":"7d52123b170c12f5","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care mutații genice sunt identificate ca fiind un factor etiopatogenic în cazul anodonțiilor?","options":[{"id":"A","text":"Mutații la nivelul genelor MSX1/MSX2 și PAX9"},{"id":"B","text":"Mutații la nivelul genelor RUNX2 și COL1A1"},{"id":"C","text":"Mutații exclusive la nivelul genei PAX9"},{"id":"D","text":"Absența tuturor dinților de pe o arcadă"},{"id":"E","text":"Deleții cromozomiale pe cromozomul X"}],"correct":["A"],"pages":[463],"source":"set-2"},{"id":"set2-9_5s3Amt","fingerprint":"afc5e8ecc1cc9df3","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele modele de transmitere ereditară au fost luate în considerare în etiopatogenia anodonției?","options":[{"id":"A","text":"Modele ereditare legate de sex"},{"id":"B","text":"Etiopatogenie poligenică multifactorială"},{"id":"C","text":"Autozomal recesiv"},{"id":"D","text":"Autozomal dominant neregulat"},{"id":"E","text":"Transmitere exclusiv mitocondrială"}],"correct":["A","B","C","D"],"pages":[463],"source":"set-2"},{"id":"set2-VLIZ3IYF","fingerprint":"0a5ac804d4446072","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Cum este definită, în scop didactic, anodonția redusă?","options":[{"id":"A","text":"Absența a mai mult de 2 dinți de pe o arcadă completă"},{"id":"B","text":"Absența a 1-2 dinți de pe o arcadă completă"},{"id":"C","text":"Absența a 1-2 dinți de pe o hemiarcadă"},{"id":"D","text":"Absența exclusivă a molarilor de minte"},{"id":"E","text":"Absența a mai mult de 2 dinți de pe o hemiarcadă"}],"correct":["C"],"pages":[463],"source":"set-2"},{"id":"set2-cVkSwOXh","fingerprint":"0a726b288e69b034","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următorii dinți sunt menționați ca fiind frecvent afectați de anodonția redusă, sub impactul evoluției filogenetice?","options":[{"id":"A","text":"Premolarii 2"},{"id":"B","text":"Molarii de minte"},{"id":"C","text":"Incisivii laterali superiori"},{"id":"D","text":"Incisivii centrali inferiori"},{"id":"E","text":"Caninii superiori"}],"correct":["A","B","C","D"],"pages":[463],"source":"set-2"},{"id":"set2-5PmJPtgI","fingerprint":"ad2a2cc43a957488","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În cazul anodonției asimetrice de incisiv lateral superior, care este o caracteristică posibilă a incisivului lateral omolog prezent pe arcadă?","options":[{"id":"A","text":"Prezintă întotdeauna o anomalie de poziție"},{"id":"B","text":"Este întotdeauna un dinte temporar persistent"},{"id":"C","text":"Este întotdeauna de dimensiuni normale"},{"id":"D","text":"Poate fi normal sau nanic"},{"id":"E","text":"Este întotdeauna afectat de carie"}],"correct":["D"],"pages":[463],"source":"set-2"},{"id":"set2-gGzcL3f3","fingerprint":"ecbdfec845ee4ccb","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este mecanismul principal care explică întârzierea procesului de rizaliză a incisivilor laterali temporari în cazurile de anodonție a succesorilor permanenți?","options":[{"id":"A","text":"Prezența unei bariere fizice create de osul alveolar dens"},{"id":"B","text":"Pierderea stimulului funcțional prin rămânerea sub planul de ocluzie"},{"id":"C","text":"O predispoziție genetică pentru rizaliză lentă"},{"id":"D","text":"Accelerarea vitezei de rezorbție radiculară de către forțele masticatorii"},{"id":"E","text":"Oprirea procesului de rezorbție datorită contactului funcțional permanent"}],"correct":["B"],"pages":[463],"source":"set-2"},{"id":"set2-w5WP248u","fingerprint":"5b8ad4bbd8040ff2","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce factor complică situația clinică în anodonția de incisiv lateral superior, ducând la depistarea tardivă a anomaliei și limitarea opțiunilor terapeutice?","options":[{"id":"A","text":"Persistența incisivului lateral temporar pe arcadă"},{"id":"B","text":"Absența simptomelor estetice în fazele incipiente"},{"id":"C","text":"Dezvoltarea unui incisiv lateral omolog nanic"},{"id":"D","text":"Erupția întârziată a caninului permanent"},{"id":"E","text":"Închiderea rapidă și completă a spațiului prin migrarea dinților vecini"}],"correct":["A"],"pages":[463],"source":"set-2"},{"id":"set2-a8hs6Los","fingerprint":"a081873a548bd07f","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt unele dintre modificările consecutive care pot însoți anodonția de incisiv lateral superior?","options":[{"id":"A","text":"Lărgirea arcadei alveolare superioare."},{"id":"B","text":"Micșorarea etajului inferior al feței."},{"id":"C","text":"Ascunderea mentonului prin inversarea treptei labiale."},{"id":"D","text":"Dezvoltarea insuficientă a arcadei alveolare superioare."},{"id":"E","text":"Stabilirea unor rapoarte de ocluzie inversă frontală."}],"correct":["B","D","E"],"pages":[464],"source":"set-2"},{"id":"set2-2dpM-jcu","fingerprint":"5cd8e116970070ad","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce explicație este oferită pentru longevitatea crescută a molarului II temporar în cazurile de anodonție de premolar 2?","options":[{"id":"A","text":"Procesul de reincluzie care îl protejează de forțele ocluzale directe."},{"id":"B","text":"Stimulul funcțional favorabil din timpul masticației, datorită menținerii la nivelul planului de ocluzie."},{"id":"C","text":"Absența forțelor de mezializare exercitate de dinții vecini."},{"id":"D","text":"O structură a smalțului mai rezistentă la atacul carios comparativ cu dinții permanenți."},{"id":"E","text":"Prezența unor rădăcini mai lungi și mai robuste decât cele ale premolarilor."}],"correct":["B"],"pages":[464],"source":"set-2"},{"id":"set2-pF_81HDa","fingerprint":"4ddf22db59926410","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În ce situație anodonția de molar de minte este considerată un factor agravant?","options":[{"id":"A","text":"Când este prezentă unilateral la maxilar."},{"id":"B","text":"Când se asociază incongruențelor dento-alveolare cu înghesuire."},{"id":"C","text":"Când se asociază extracțiilor molarilor de 6 ani sau celor de 12 ani."},{"id":"D","text":"Când caninul de pe aceeași hemiarcadă este inclus."},{"id":"E","text":"Când nu se asociază cu nicio altă anomalie dento-maxilară."}],"correct":["C"],"pages":[464],"source":"set-2"},{"id":"set2-2c9Zc1U4","fingerprint":"ee2f3754c7a83de5","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele afirmații descriu corect anodonția de canin?","options":[{"id":"A","text":"Este un fenomen extrem de rar."},{"id":"B","text":"A fost observată mai frecvent la maxilar decât la mandibulă."},{"id":"C","text":"Originea sa este considerată a fi mai degrabă genetică."},{"id":"D","text":"Se manifestă în majoritatea cazurilor în formă unilaterală."},{"id":"E","text":"Este frecvent asociată cu persistența caninului temporar până la 45-50 de ani."}],"correct":["A","B","C"],"pages":[464],"source":"set-2"},{"id":"set2-JRRuKVS_","fingerprint":"be9ea9e851a8ad31","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Ce tulburări funcționale complexe pot fi antrenate de anodonția ambilor incisivi centrali inferiori?","options":[{"id":"A","text":"Dezvoltarea insuficientă a arcadei alveolare inferioare."},{"id":"B","text":"Reincaluzia molarilor II temporari."},{"id":"C","text":"Crearea unei breșe mari, similare celei din edentație."},{"id":"D","text":"Tulburări de ocluzie și parodontale."},{"id":"E","text":"Tulburări fonetice."}],"correct":["D","E"],"pages":[464],"source":"set-2"},{"id":"set2-HkRC05mJ","fingerprint":"919b44e7cd885b33","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce caracteristici definesc anodonția redusă atipică?","options":[{"id":"A","text":"Antrenarea unor tulburări clinice și funcționale minore."},{"id":"B","text":"Rezolvarea terapeutică facilă, fără probleme majore."},{"id":"C","text":"Confirmarea ipotezelor etiopatogenice clasice."},{"id":"D","text":"Afectarea predictibilă și simetrică a dinților."},{"id":"E","text":"Interesarea unui număr variat de dinți și/sau interesarea diferențiată a dinților din același grup."}],"correct":["E"],"pages":[464],"source":"set-2"},{"id":"set2-fS-2GnH8","fingerprint":"f93c4934b0dce0ca","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"În cazul absenței predecesorului temporar în anodonția de premolar 2, ce manifestări clinico-funcționale pot apărea?","options":[{"id":"A","text":"Proeminența mentonului."},{"id":"B","text":"Denivelarea planului de ocluzie."},{"id":"C","text":"Modificarea relațiilor de ocluzie statice și dinamice."},{"id":"D","text":"Apariția unei breșe mari, similare celei din edentație."},{"id":"E","text":"Îmbunătățirea rapoartelor de ocluzie prin închiderea spontană a spațiului."}],"correct":["B","C"],"pages":[464],"source":"set-2"},{"id":"set2-QPP19XjT","fingerprint":"37ed3275c4aa8812","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele afirmații definesc anodonția întinsă?","options":[{"id":"A","text":"Poate afecta creșterea și dezvoltarea facială, deoarece dinții sunt centre osteogenetice de creștere secundară."},{"id":"B","text":"Afectează întotdeauna un singur maxilar și are o distribuție asimetrică."},{"id":"C","text":"Se caracterizează prin lipsa a mai mult de 2 dinți de pe o hemiarcadă."},{"id":"D","text":"Interesează frecvent ambele maxilare, cu o topografie de obicei simetrică."},{"id":"E","text":"Include doar cazurile în care lipsesc toți dinții de pe arcadă (anodonții totale)."}],"correct":["A","C","D"],"pages":[465],"source":"set-2"},{"id":"set2-TgmBuonZ","fingerprint":"7fa362509438fc61","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Ce modificări faciale sunt caracteristice în anodonțiile subtotale și totale?","options":[{"id":"A","text":"Etajul inferior al feței este micșorat."},{"id":"B","text":"Etajul inferior al feței este mărit datorită erupției compensatorii."},{"id":"C","text":"Buza inferioară este răsfrântă."},{"id":"D","text":"Mentonul este șters și șanțul labio-mentonier este diminuat."},{"id":"E","text":"Profilul facial devine concav."}],"correct":["A","C","E"],"pages":[465],"source":"set-2"},{"id":"set2-pHeawmE3","fingerprint":"4c8b81a302ae2465","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt caracteristicile dinților prezenți în cazurile de anodonție subtotală?","options":[{"id":"A","text":"Au întotdeauna o morfologie normală, dar sunt malpoziționați."},{"id":"B","text":"Sunt distribuiți asimetric pe arcade."},{"id":"C","text":"Sunt reduși ca volum și au o formă atipică."},{"id":"D","text":"Au rădăcini scurte."},{"id":"E","text":"Prezintă un volum mărit (macrodontie) compensator."}],"correct":["C","D"],"pages":[465],"source":"set-2"},{"id":"set2-h8-OOt5G","fingerprint":"11a0bcb26ffcf72b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Ce semne sistemice pot însoți anodonțiile subtotale și totale, exprimând o afectare a sistemului ectodermal?","options":[{"id":"A","text":"Hipotricoză cu păr friabil."},{"id":"B","text":"Dezvoltare accelerată a fanerelor (păr și unghii)."},{"id":"C","text":"Piele umedă și hipersecreție sudoripară."},{"id":"D","text":"Modificări ale membrelor precum hipodactilia și sindactilia."},{"id":"E","text":"Absența glandelor sudoripare și tulburări de termoreglare."}],"correct":["A","D","E"],"pages":[465],"source":"set-2"},{"id":"set2-LhNjQOJC","fingerprint":"0cb7134d88e1041e","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"În contextul căror boli sistemice anodonția subtotală sau totală poate reprezenta un semn patognomonic?","options":[{"id":"A","text":"Amelogeneza imperfectă."},{"id":"B","text":"Sindromul Bloch-Sulzberg (incontinentia pigmenti)."},{"id":"C","text":"Sindromul Down (trisomia 21)."},{"id":"D","text":"Displazia ectodermală."},{"id":"E","text":"Boala parodontală juvenilă."}],"correct":["B","C","D"],"pages":[465],"source":"set-2"},{"id":"set2-RqFeUrRU","fingerprint":"8447c905cfaae136","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este metoda de examinare considerată indispensabilă pentru stabilirea diagnosticului de anodonție?","options":[{"id":"A","text":"Modelele de studiu."},{"id":"B","text":"Examenul radiologic."},{"id":"C","text":"Testele genetice."},{"id":"D","text":"Examenul clinic intraoral și extraoral."},{"id":"E","text":"Anamneza detaliată a pacientului."}],"correct":["B"],"pages":[465],"source":"set-2"},{"id":"set2-bDCNwutg","fingerprint":"14136393e9a9bb33","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următorii dinți sunt cel mai frecvent afectați de anodonție, conform regulii generale din cazul teoriei proterogenetice?","options":[{"id":"A","text":"Incisivii centrali inferiori."},{"id":"B","text":"Primii molari permanenți."},{"id":"C","text":"Caninii superiori."},{"id":"D","text":"Premolarii secunzi."},{"id":"E","text":"Incisivii laterali superiori."}],"correct":["D","E"],"pages":[465],"source":"set-2"},{"id":"set2-cRQjUenO","fingerprint":"7d45d7ee429efdcd","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Ce elemente clinice pot conduce la diagnosticul de anodonție redusă?","options":[{"id":"A","text":"Absența dinților permanenți la o vârstă la care ar fi trebuit să erupă."},{"id":"B","text":"Dismorfoze ale dinților permanenți existenți, precum dinții conici sau nanici."},{"id":"C","text":"Prezența dinților supranumerari."},{"id":"D","text":"Persistența dinților temporari mult peste termenul normal de permutare."},{"id":"E","text":"Erupția precoce a tuturor dinților permanenți."}],"correct":["A","B","D"],"pages":[465],"source":"set-2"},{"id":"set2-xKjXWCcE","fingerprint":"28b157f5e06e3d4c","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În cazul unei anodonții reduse, când pe arcadă persistă dintele temporar, care este principalul diagnostic diferențial?","options":[{"id":"A","text":"Incluzia dintelui permanent."},{"id":"B","text":"Fuziunea dentară."},{"id":"C","text":"Extracția dintelui permanent."},{"id":"D","text":"Transpoziția dentară."},{"id":"E","text":"Anchiloza dintelui temporar."}],"correct":["A"],"pages":[465],"source":"set-2"},{"id":"set2-9XPBTvAf","fingerprint":"b5c74b1d4fa2721b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În contextul unei anodonții reduse, la un pacient la care dintele temporar persistă pe arcadă, cu ce afecțiune se face diagnosticul diferențial și prin ce metode se stabilește diagnosticul?","options":[{"id":"A","text":"Se face cu extracția dintelui permanent, diagnosticul fiind confirmat exclusiv prin examen radiologic."},{"id":"B","text":"Se face cu incluzia dintelui permanent, diagnosticul bazându-se pe examen clinic și radiologic."},{"id":"C","text":"Se face cu extracția dintelui permanent, diagnosticul fiind confirmat prin anamneză și examen clinic."},{"id":"D","text":"Se face cu incluzia dintelui permanent, diagnosticul de certitudine fiind stabilit exclusiv prin examen clinic care evidențiază o creastă subțiată."},{"id":"E","text":"Se face atât cu incluzia, cât și cu extracția dintelui permanent, diagnosticul fiind stabilit prin teleradiografie."}],"correct":["B"],"pages":[466],"source":"set-2"},{"id":"set2-i02XInKL","fingerprint":"d3081689558e3c49","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce tip de examen radiologic este considerat obligatoriu în cazul anodonțiilor și de ce?","options":[{"id":"A","text":"Ortopantomograma, deoarece anomalia se limitează rar la un singur dinte și este necesară o imagine de ansamblu."},{"id":"B","text":"Teleradiografia de profil, deoarece permite evaluarea exactă a direcției de creștere a maxilarelor."},{"id":"C","text":"Teleradiografia frontală, deoarece este cea mai utilă pentru a cuantifica tulburările de dezvoltare cantitative."},{"id":"D","text":"Radiografiile seriate retroalveolare, pentru a urmări evoluția sub tratament a fiecărui dinte în parte."},{"id":"E","text":"Ortopantomograma, deoarece este singura investigație care poate exclude o incluzie înaltă."}],"correct":["A"],"pages":[466],"source":"set-2"},{"id":"set2-s9sf-DD-","fingerprint":"d5c3ef7e5665d281","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele informații pot fi obținute prin efectuarea unei singure ortopantomograme la un pacient cu anodonție?","options":[{"id":"A","text":"Determinarea gradului de dezvoltare al dinților."},{"id":"B","text":"Evidențierea reactivității biologice a pacientului și urmărirea evoluției sub tratament."},{"id":"C","text":"Evaluarea numărului dinților temporari și permanenți."},{"id":"D","text":"Analizarea deplasărilor dentare dirijate ortodontic."},{"id":"E","text":"Aprecierea poziției intraosoase și a anatomiei dinților prezenți."}],"correct":["A","C","E"],"pages":[466],"source":"set-2"},{"id":"set2-5_KLzwIu","fingerprint":"d4bee96ef301fd03","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Ce informații specifice despre aparatul dento-maxilar furnizează teleradiografia în cazul pacienților cu anodonție?","options":[{"id":"A","text":"Aprecierea foarte exactă a direcției de creștere a elementelor osoase prin calcularea unor unghiuri."},{"id":"B","text":"Imaginea de ansamblu a ambelor arcade pentru evaluarea numărului de dinți absenți."},{"id":"C","text":"Date despre structura și rapoartele tuturor elementelor aparatului dento-maxilar între ele."},{"id":"D","text":"Cuantificarea tulburărilor de dezvoltare cantitative, de ritm, de poziție și de direcție."},{"id":"E","text":"Evaluarea reactivității biologice a pacientului la tratamentul ortodontic."}],"correct":["A","C","D"],"pages":[466],"source":"set-2"},{"id":"set2-BU4ynWD1","fingerprint":"589342788443e220","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce incidență teleradiografică este considerată cea mai utilă în evaluarea unui caz de anodonție?","options":[{"id":"A","text":"Axială"},{"id":"B","text":"Frontală"},{"id":"C","text":"De profil"},{"id":"D","text":"Oblică"},{"id":"E","text":"Panoramica"}],"correct":["B"],"pages":[466],"source":"set-2"},{"id":"set2-OEJ89cUk","fingerprint":"b60e3918c53150b3","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt caracteristicile strategiei terapeutice în cazul anodonțiilor întinse?","options":[{"id":"A","text":"Rolul principal în tratament revine exclusiv medicului ortodont."},{"id":"B","text":"Se concentrează exclusiv pe restaurarea protetică după finalizarea creșterii."},{"id":"C","text":"Rezolvarea terapeutică trebuie să fie urgentă și adecvată vârstei pacientului."},{"id":"D","text":"Planificarea trebuie să fie cât mai precoce pentru a utiliza resursele din perioada de creștere."},{"id":"E","text":"Este o strategie de lungă durată care necesită colaborare interdisciplinară."}],"correct":["C","D","E"],"pages":[466],"source":"set-2"},{"id":"set2-Rt_dW9HF","fingerprint":"2add428e4d528178","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce mișcare dentară fiziologică are un potențial redus sau absent în cazurile de anodonție, reprezentând o dificultate în tratamentul ortodontic?","options":[{"id":"A","text":"Mișcarea de extruzie"},{"id":"B","text":"Mișcarea de distalizare"},{"id":"C","text":"Mișcarea de rotație"},{"id":"D","text":"Mișcarea de intruzie"},{"id":"E","text":"Mișcarea de mezializare"}],"correct":["E"],"pages":[466],"source":"set-2"},{"id":"set2-WZ3nn4ea","fingerprint":"ede286a4db70627b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În cazul absenței dintelui permanent și a predecesorului său temporar de pe arcadă, ce aspect clinic al crestei alveolare este frecvent sugestiv pentru anodonție, în comparație cu o creastă rezultată postextracțional?","options":[{"id":"A","text":"O creastă subțiată, de aspect concav."},{"id":"B","text":"O creastă mai bine conformată, similară cu zonele edentate postextracțional."},{"id":"C","text":"O creastă lățită, de aspect convex."},{"id":"D","text":"O creastă cu o bombare vizibilă, similară incluziilor joase."},{"id":"E","text":"O creastă fără modificări dimensionale vizibile."}],"correct":["A"],"pages":[466],"source":"set-2"},{"id":"set2-jHrZgu56","fingerprint":"d8f66d82cd38da26","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt factorii care influențează decizia terapeutică în ortodonție?","options":[{"id":"A","text":"Localizarea anomaliei, contextul general oro-dentar și starea dinților temporari."},{"id":"B","text":"Exclusiv speranțele prognostice pentru o dentiție estetică la vârsta adultă."},{"id":"C","text":"Potențialul biologic al pacientului."},{"id":"D","text":"Tipul de aparat ortodontic preferat de către pacient."},{"id":"E","text":"Severitatea anomaliei, momentul depistării și vârsta pacientului."}],"correct":["A","C","E"],"pages":[467],"source":"set-2"},{"id":"set2-5CSdVqSe","fingerprint":"00ec999063e54876","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În ce condiții este indicată păstrarea pe arcadă a unui dinte temporar în cazul anodonției dintelui succesional?","options":[{"id":"A","text":"Indiferent de prezența rizalizei, dacă dintele este indemn de carie."},{"id":"B","text":"Exclusiv în cazul molarului doi temporar, indiferent de starea sa coronară."},{"id":"C","text":"Dacă dintele temporar prezintă o mobilitate redusă, chiar și în prezența cariilor."},{"id":"D","text":"În cazul dinților frontali, pentru a menține spațiul până la 18-20 de ani."},{"id":"E","text":"Când rizaliza rădăcinilor este absentă și dintele nu prezintă leziuni carioase întinse."}],"correct":["E"],"pages":[467],"source":"set-2"},{"id":"set2-OzalC17z","fingerprint":"59600682f3f692c2","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt motivele pentru care dinții frontali temporari nu beneficiază de terapie conservatoare în caz de anodonție a succesorilor permanenți?","options":[{"id":"A","text":"Rădăcinile lor interferează cu erupția dinților vecini."},{"id":"B","text":"Prezintă întotdeauna rizaliză accentuată la vârsta permutării dentare."},{"id":"C","text":"Sunt mai predispuși la leziuni carioase decât molarii temporari."},{"id":"D","text":"Diferă mult de corespondenții lor definitivi ca dimensiune, formă și culoare."},{"id":"E","text":"Au o existență relativă, rămânând pe arcadă doar până în jurul vârstei de 18-20 de ani."}],"correct":["D","E"],"pages":[467],"source":"set-2"},{"id":"set2-ViHrNKob","fingerprint":"107b4866a2ba6cf7","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt cele două variante terapeutice posibile pentru managementul breșei rezultate după extracția unui dinte temporar într-un caz de anodonție?","options":[{"id":"A","text":"Menținerea spațiilor pentru rezolvare implanto-protetică sau protetică."},{"id":"B","text":"Menținerea spațiilor pentru rezolvare implanto-protetică și lăsarea breșei neocupate permanent."},{"id":"C","text":"Închiderea spațiilor prin dirijare ortodontică."},{"id":"D","text":"Închiderea spațiilor prin migrare naturală și utilizarea unei proteze mobile parțiale imediate."},{"id":"E","text":"Extracția dinților vecini pentru simetrie și închiderea ortodontică a spațiilor."}],"correct":["A","C"],"pages":[467],"source":"set-2"},{"id":"set2-Wzdro-Cn","fingerprint":"20b56e60ae147387","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce presupune tehnica extracției dirijate în cazul anodonțiilor reduse la maxilarul superior?","options":[{"id":"A","text":"Extracția incisivilor laterali superiori temporari, urmată de cea a caninilor superiori temporari."},{"id":"B","text":"Amânarea oricărei extracții până la erupția completă a premolarilor."},{"id":"C","text":"Extracția simultană a incisivilor centrali și laterali temporari pentru a accelera migrarea."},{"id":"D","text":"Extracția molarului doi temporar pentru a permite mezializarea întregului segment lateral."},{"id":"E","text":"Extracția caninilor superiori temporari, urmată de cea a incisivilor laterali superiori temporari."}],"correct":["A"],"pages":[467],"source":"set-2"},{"id":"set2-ja20uWfa","fingerprint":"32d4e07c863a04f4","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Din ce cauză deplasările meziale ale dinților prin aparate ortodontice în cazurile de anodonție se realizează cu dificultate?","options":[{"id":"A","text":"Deoarece aparatele ortodontice nu pot genera forțe pentru deplasarea corporeala."},{"id":"B","text":"Din cauza lipsei de suport osos și a fibrelor parodontale transseptale."},{"id":"C","text":"Din cauza amplitudinii mai mari a migrărilor dentare la maxilarul inferior."},{"id":"D","text":"Datorită rezistenței crescute a dinților temporari adiacenți."},{"id":"E","text":"Datorită tendinței fiziologice de distalizare a dinților în aceste cazuri."}],"correct":["B"],"pages":[467],"source":"set-2"},{"id":"set2-tav3vSZJ","fingerprint":"2156f0b0f840b3ad","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este principalul dezavantaj al unei soluții protetice pentru tratarea anodonției, în comparație cu tratamentul ortodontic de închidere a spațiilor?","options":[{"id":"A","text":"Rezultatul estetic este întotdeauna inferior celui obținut prin ortodonție."},{"id":"B","text":"Este o soluție terapeutică ce se întinde pe mai mulți ani."},{"id":"C","text":"Implică întotdeauna extracția dinților temporari sănătoși."},{"id":"D","text":"Atrage necesitatea unei asistențe stomatologice continue, pe tot restul vieții."},{"id":"E","text":"Nu poate fi aplicată în cazul anodonțiilor frontale reduse."}],"correct":["D"],"pages":[467],"source":"set-2"},{"id":"set2-67a2iv5F","fingerprint":"400d2362fb18aa02","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt obiectivele tratamentului ortodontic în situațiile în care spațiile edentate sunt prea mari pentru a fi închise sau reduse ortodontic?","options":[{"id":"A","text":"Asigurarea paralelismului dinților existenți pentru a permite aplicarea ulterioară a unor soluții protetice."},{"id":"B","text":"Stimularea dezvoltării oaselor maxilare și asigurarea unor rapoarte normale între maxilare."},{"id":"C","text":"Dirijarea erupției dentare și distribuția optimă a dinților prezenți pe arcadă."},{"id":"D","text":"Aplicarea imediată a soluțiilor implanto-protetice definitive, indiferent de vârsta pacientului."},{"id":"E","text":"Blocarea proceselor de creștere ale oaselor maxilare pentru a stabiliza arcadele."}],"correct":["A","B","C"],"pages":[468],"source":"set-2"},{"id":"set2--vYoPMUO","fingerprint":"2c325788fc371e15","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Ce particularități sunt menționate în abordarea terapeutică a anodonțiilor totale?","options":[{"id":"A","text":"Un suport dento-alveolar nefavorabil pentru menținerea și stabilitatea aparatelor ortodontice."},{"id":"B","text":"Finalizarea proceselor de creștere la nivelul masivului facial, permițând protezarea imediată."},{"id":"C","text":"Prezența unui suport dento-alveolar favorabil, care facilitează aplicarea forțelor ortodontice."},{"id":"D","text":"Existența unui organism aflat într-un proces de creștere și dezvoltare."},{"id":"E","text":"Similitudinea problemelor terapeutice cu cele din edentațiile de mică amploare."}],"correct":["A","D"],"pages":[468],"source":"set-2"},{"id":"set2-ItBilkn4","fingerprint":"62307106adbd50ea","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Pe lângă conformarea substratului osos, ce alte obiective specifice vizează tratamentul ortodontic în anodonția totală?","options":[{"id":"A","text":"Menținerea unui suport dento-alveolar subdezvoltat pentru a facilita inserarea implanturilor."},{"id":"B","text":"Asigurarea cadrului pentru desfășurarea normală a funcțiilor, în special pentru alimentarea copilului."},{"id":"C","text":"Obținerea unei dimensiuni verticale corecte a etajului inferior și a unui profil fizionomic îmbunătățit."},{"id":"D","text":"Creșterea eficienței masticatorii."},{"id":"E","text":"Realizarea protezării cu caracter definitiv în jurul vârstei de 10-12 ani."}],"correct":["B","C","D"],"pages":[468],"source":"set-2"},{"id":"set2-9EkgA1rH","fingerprint":"d6c7211f788c103b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este momentul considerat oportun pentru realizarea protezării cu caracter definitiv în cazurile de anodonții întinse, subtotale și totale?","options":[{"id":"A","text":"După vârsta de 16-18 ani."},{"id":"B","text":"În copilăria timpurie, pentru a stimula funcțiile aparatului dento-maxilar."},{"id":"C","text":"La debutul pubertății, pentru a beneficia de puseul de creștere."},{"id":"D","text":"Imediat după finalizarea tratamentului ortodontic, indiferent de vârsta pacientului."},{"id":"E","text":"Oricând după distribuția optimă a dinților pe arcadă prin tratament ortodontic."}],"correct":["A"],"pages":[468],"source":"set-2"},{"id":"set2-w29l65jV","fingerprint":"08e7f2e54692da0b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este scopul principal al tratamentului ortodontic în anodonțiile întinse, subtotale și totale?","options":[{"id":"A","text":"Crearea unei ocluzii stabile fără a necesita intervenții protetice ulterioare."},{"id":"B","text":"Conformarea substratului osos și dentar pentru viitoare tratamente implanto-protetice."},{"id":"C","text":"Realizarea unei soluții protetice fixe cu caracter temporar."},{"id":"D","text":"Închiderea completă a tuturor spațiilor edentate."},{"id":"E","text":"Prevenirea erupției dinților existenți pentru a conserva spațiul."}],"correct":["B"],"pages":[468],"source":"set-2"},{"id":"set2-a8cOcERv","fingerprint":"159924c3fe4a819b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt mecanismele etiopatogenice responsabile pentru apariția anodonției?","options":[{"id":"A","text":"Fuziunea mugurilor dentari adiacenți"},{"id":"B","text":"Neformarea mugurilor dentari"},{"id":"C","text":"Atrofia mugurilor dentari"},{"id":"D","text":"Hiperplazia laminei dentare"},{"id":"E","text":"Lipsa de dezvoltare embrionară"}],"correct":["B","C","E"],"pages":[460],"source":"set-2"},{"id":"set2-wKN9ZzpD","fingerprint":"00bf77f84c25541f","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele afirmații referitoare la datele epidemiologice ale anodonției sunt adevărate?","options":[{"id":"A","text":"Sexul feminin este afectat într-o proporție aproape dublă față de sexul masculin."},{"id":"B","text":"Reducerea numerică are o frecvență de 16 ori mai mare în dentiția temporară."},{"id":"C","text":"Incidența anodonției este mai mare la sexul masculin, trăsătură comună cu anomalia prin dinți supranumerari."},{"id":"D","text":"Frecvența anodonției în raport cu alte anomalii dento-maxilare este cuprinsă între 2 și 10%."},{"id":"E","text":"Afecțiunea se manifestă exclusiv în dentiția permanentă."}],"correct":["A","D"],"pages":[460],"source":"set-2"},{"id":"set2-HJFW26ZB","fingerprint":"c4cf6ae1ddd70b7b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt dinții plasați pe primele locuri în ordinea frecvenței de interesare de către anodonție?","options":[{"id":"A","text":"Incisivul lateral superior"},{"id":"B","text":"Molarii de minte"},{"id":"C","text":"Molarul de 12 ani"},{"id":"D","text":"Incisivul central superior"},{"id":"E","text":"Al doilea premolar inferior"}],"correct":["A","B","E"],"pages":[460],"source":"set-2"},{"id":"set2-e072vVml","fingerprint":"f2128ef5c4dced6f","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Ce caracteristici prezintă anodonția în ceea ce privește distribuția pe sexe și tipuri de dentiție?","options":[{"id":"A","text":"Prezintă o afectare aproape dublă a sexului feminin în raport cu cel masculin."},{"id":"B","text":"Afectează predominant sexul masculin, cu o frecvență mai mare în dentiția temporară."},{"id":"C","text":"Incidența este mai mare pentru sexul masculin, la fel ca în cazul dinților supranumerari."},{"id":"D","text":"Este o anomalie caracterizată prin limitarea strictă la nivelul dentiției permanente."},{"id":"E","text":"Raportul de afectare a dentiției temporare față de cea permanentă este de 16/1."}],"correct":["A"],"pages":[460],"source":"set-2"},{"id":"set2-UKgidlf8","fingerprint":"1b252673f283c38b","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următorii dinți prezintă o frecvență rară sau foarte rară de implicare în anodonție?","options":[{"id":"A","text":"Incisivul lateral inferior"},{"id":"B","text":"Incisivul central inferior"},{"id":"C","text":"Incisivul lateral superior"},{"id":"D","text":"Premolarul 2 superior"},{"id":"E","text":"Molarul de 6 ani"}],"correct":["A","D","E"],"pages":[461],"source":"set-2"},{"id":"set2-2zqy5i1r","fingerprint":"9e23e56a5626bd3e","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este dintele care se abate de la regula interesării ultimului dinte din fiecare grup în procesul de modificare filogenetică a formulei dentare?","options":[{"id":"A","text":"Incisivul lateral superior"},{"id":"B","text":"Incisivul central inferior"},{"id":"C","text":"Molarul de minte superior"},{"id":"D","text":"Al doilea premolar superior"},{"id":"E","text":"Al doilea premolar inferior"}],"correct":["B"],"pages":[461],"source":"set-2"},{"id":"set2-wSb8-eed","fingerprint":"46c0bd1572f9b7de","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt etapele descrise de Quinet pentru a explica procesul de dispariție a unui dinte din formula dentară?","options":[{"id":"A","text":"Menținerea constantă a poziției și morfologiei în ciuda lipsei de material embrionar"},{"id":"B","text":"Labilitatea volumetrică, morfologică și variabilitatea de poziție"},{"id":"C","text":"Trecerea de la biradiculație la monoradiculație și reducerea dimensiunii dentare"},{"id":"D","text":"Încorporarea parțială a dintelui de către un dinte vecin"},{"id":"E","text":"Trecerea de la monoradiculație la biradiculație și creșterea dimensiunii dentare"}],"correct":["B","C","D"],"pages":[461],"source":"set-2"},{"id":"set2-NTCtRelK","fingerprint":"fea550eb76f5a8be","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele mecanisme sunt implicate în producerea anodonțiilor conform teoriilor ontogenetice?","options":[{"id":"A","text":"Distrugerea lamei dentare prin acțiune directă în prima lună de sarcină"},{"id":"B","text":"Modificări în sinteza acizilor nucleici induse de lipsa de oxigen"},{"id":"C","text":"Insuficiența potențialului formativ al teritoriilor prezumtiv odontogene prin lipsa unui inductor primar"},{"id":"D","text":"Insuficiența potențialului evolutiv prin reducerea proceselor metabolice celulare sub nivelul de supraviețuire"},{"id":"E","text":"Distrugerea germenilor dentari formați prin epuizarea distală a gradientului de molarizare"}],"correct":["B","C","D"],"pages":[462],"source":"set-2"},{"id":"set2-pMirygB6","fingerprint":"38b7f413c5104fca","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următorii constituie factori locali cu potențial etiologic în apariția anodonțiilor?","options":[{"id":"A","text":"Consumul irațional și abuziv de alcool în timpul sarcinii"},{"id":"B","text":"Despicăturile labio-maxilo-palatine"},{"id":"C","text":"Iradierile loco-regionale în primii ani de viață"},{"id":"D","text":"Procesele supurative periapicale ale dinților temporari"},{"id":"E","text":"Boli infecto-contagioase ale mamei în timpul sarcinii"}],"correct":["B","C","D"],"pages":[462],"source":"set-2"},{"id":"set2-QysS0A-E","fingerprint":"b168638759eb6564","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care dintre următoarele afirmații descrie mecanismul genetic incriminat în determinismul anodonțiilor?","options":[{"id":"A","text":"Tulburările în dezvoltarea dinților debutează prin epuizarea cantitativă a materialului mezodermal post-eruptiv"},{"id":"B","text":"Mutațiile la nivelul genelor MSX1/MSX2 și PAX9 se exprimă la nivelul țesuturilor dentare în debutul dezvoltării dinților"},{"id":"C","text":"Anodonția este produsă exclusiv printr-un model autozomal recesiv independent de sex"},{"id":"D","text":"Transmiterea autozomal dominantă neregulată este exclusă pentru absența incisivului lateral superior"},{"id":"E","text":"Anodonțiile sunt provocate de activarea intempestivă a gradientului de incisivizare"}],"correct":["B"],"pages":[463],"source":"set-2"},{"id":"set2-HMb9flPd","fingerprint":"88958d2813eb96d7","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele afirmații sunt adevărate cu privire la dinamica dinților temporari în cazul anodonției dinților succesionali?","options":[{"id":"A","text":"Forțele masticatorii opresc procesul de rezorbție radiculară a dintelui temporar dacă acesta pierde contactul cu planul de ocluzie."},{"id":"B","text":"Molarii II temporari pot persista pe arcadă până la vârsta de 45-50 de ani datorită stimulului funcțional menținut de poziția lor în planul de ocluzie."},{"id":"C","text":"Incisivii laterali temporari rămân adesea deasupra planului de ocluzie după permutarea dentară, ceea ce întârzie procesul de rizaliză inițială."},{"id":"D","text":"Absența dintelui succesional garantează retenția nedefinită a dinților temporari pe arcadă, independent de solicitările masticatorii."},{"id":"E","text":"Accelerarea procesului de rizaliză a incisivilor laterali temporari în jurul vârstei de 18 ani este determinată de lipsa stimulului funcțional masticator."}],"correct":["B","E"],"pages":[463],"source":"set-2"},{"id":"set2-j7GOIfdU","fingerprint":"8402cff460e5efc4","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt modificările faciale și ocluzale care se asociază frecvent cu anodonția de incisiv lateral superior?","options":[{"id":"A","text":"Dezvoltarea insuficientă a arcadei alveolare superioare."},{"id":"B","text":"Accentuarea treptei labiale în plan sagital."},{"id":"C","text":"Instalarea unor rapoarte de ocluzie adâncă acoperită frontală."},{"id":"D","text":"Proeminența mentonului."},{"id":"E","text":"Micșorarea etajului inferior al feței."}],"correct":["A","D","E"],"pages":[464],"source":"set-2"},{"id":"set2-CI28aqlc","fingerprint":"b30dbd98f557c1ea","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care dintre următoarele afirmații descrie cel mai precis anodonția de canin?","options":[{"id":"A","text":"Interacțiunea genelor PAX9 și MSX1/MSX2 blochează procesul de agenezie dentară, protejând tiparul morfologic ancestral al caninului."},{"id":"B","text":"Apare exclusiv ca un fenomen izolat și este inițiată de absența funcțională a genelor responsabile de dezvoltarea incisivilor."},{"id":"C","text":"Se caracterizează prin incidența crescută la nivel mandibular, fiind condiționată de persistența caninului temporar peste vârsta de 20 de ani."},{"id":"D","text":"Reprezintă un fenomen extrem de rar, observat mai frecvent la maxilar, adesea bilateral, având o posibilă etiologie genetică."},{"id":"E","text":"Se manifestă frecvent unilateral la mandibulă din cauza instabilității morfologice a caninului inferior pe scara evoluției filogenetice."}],"correct":["D"],"pages":[464],"source":"set-2"},{"id":"set2-jSuL3agv","fingerprint":"922db6e9878a50fb","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"În ce mod influențează anodonția de molar de minte evoluția patologiei dento-maxilare?","options":[{"id":"A","text":"Declanșează în mod sistematic reincluzia molarului de 12 ani."},{"id":"B","text":"Remediază deficitul funcțional apărut în urma migrării orizontale a premolarilor spre spațiile edentate."},{"id":"C","text":"Conduce la edentație terminală în cazul asocierii cu extracția molarilor de 12 ani, prin lipsa stimulului tardiv de creștere sau mezializare."},{"id":"D","text":"Reprezintă un factor adjuvant în prezența incongruențelor dento-alveolare cu înghesuire."},{"id":"E","text":"Se comportă ca un factor agravant atunci când se asociază cu extracția molarilor de 6 ani."}],"correct":["C","D","E"],"pages":[464],"source":"set-2"},{"id":"set2-MrzY0r81","fingerprint":"5fcff447152db5fe","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt caracteristicile esențiale ale anodonției reduse atipice?","options":[{"id":"A","text":"Răsturnarea ipotezelor etiopatogenice clasice privind tiparele de dezvoltare a anodonției."},{"id":"B","text":"Generarea unor tulburări clinice și funcționale majore care ridică dificultăți în abordarea terapeutică."},{"id":"C","text":"Interesarea diferențiată, uneori haotică, a dinților din cadrul aceluiași grup dentar."},{"id":"D","text":"Restrângerea anomaliei exclusiv la dinții care se află sub impactul direct al evoluției filogenetice."},{"id":"E","text":"Implicarea unui număr constant și predictibil de dinți la nivelul ambelor maxilare."}],"correct":["A","B","C"],"pages":[464],"source":"set-2"},{"id":"set2-Y7mLWrFD","fingerprint":"f70b4cbd63ec7342","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care dintre următoarele afirmații descriu corect modificările structurale și faciale caracteristice anodonțiilor subtotale și totale?","options":[{"id":"A","text":"La palparea arcadelor se constată creste alveolare reduse vestibulo-oral, cu formarea unei zone fibroase înguste, mai ales la mandibulă."},{"id":"B","text":"Mentonul are un aspect șters, iar șanțul labio-mentonier este aplatizat."},{"id":"C","text":"Profilul facial este concav, cu punctul gnathion situat anterior de planul Simon."},{"id":"D","text":"În anodonția subtotală, deși dinții existenți sunt frecvent simetrici, aceștia sunt atipici ca formă, au rădăcini scurte și un volum redus."},{"id":"E","text":"Etajul inferior al feței prezintă o dimensiune verticală mărită, ca mecanism adaptativ la pierderea unităților odonto-parodontale."}],"correct":["A","C","D"],"pages":[465],"source":"set-2"},{"id":"set2-NHNES-D3","fingerprint":"824f1ef2570fcc99","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"În formele clinice de minus dentar din dentiția permanentă, regula generală vizează absența ultimului dinte din fiecare grup morfologic. Care dintre următorii dinți reprezintă excepția de la această regulă topografică?","options":[{"id":"A","text":"Premolarul secund inferior"},{"id":"B","text":"Premolarul secund superior"},{"id":"C","text":"Incisivul central inferior"},{"id":"D","text":"Incisivul lateral superior"},{"id":"E","text":"Molarul de minte"}],"correct":["C"],"pages":[465],"source":"set-2"},{"id":"set2-xsZuDveR","fingerprint":"c6039d4eeeb61ae8","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Referitor la diagnosticul diferențial al anodonției reduse, care dintre următoarele enunțuri sunt adevărate?","options":[{"id":"A","text":"Examenul radiologic este contraindicat pentru confirmarea certitudinii diagnosticului dacă pacientul prezintă semne clinice de incluzie înaltă."},{"id":"B","text":"Când dintele temporar lipsește, anodonția trebuie diferențiată de extracția dintelui permanent, post-extracțional creasta fiind mai bine conformată."},{"id":"C","text":"În incluziile dentare joase, examenul clinic obiectivează bombarea crestei alveolare."},{"id":"D","text":"Creasta alveolară rezultată în cazul anodonției prezintă o lățime crescută și o formă convexă la palpare."},{"id":"E","text":"Când pe arcadă persistă dintele temporar, diagnosticul diferențial trebuie făcut exclusiv cu extracția dintelui permanent."}],"correct":["B","C"],"pages":[465],"source":"set-2"},{"id":"set2-FfI4hJ93","fingerprint":"0ba3c3903624327e","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Anodonția subtotală sau totală poate apărea ca semn patognomonic în cadrul unor afecțiuni sistemice de origine ectodermală sau ecto-mezodermală. Care dintre următoarele entități clinice și semne asociate fac parte din acest tablou?","options":[{"id":"A","text":"Pielea cu exces de sebum, hiperhidratată și părul dens cu textură aspră."},{"id":"B","text":"Hiperplazia marcantă a glandelor sudoripare care induce episoade febrile recurente."},{"id":"C","text":"Sindactilia, hipodactilia și prezența escoriațiilor furfuracee."},{"id":"D","text":"Sindromul Down (trisomia 21) și sindromul Bloch-Sulzberg."},{"id":"E","text":"Lipsa glandelor sudoripare, generând pacienților incapacitatea de a transpira și tulburări de termoreglare."}],"correct":["C","D","E"],"pages":[465],"source":"set-2"},{"id":"set2-78PPseyX","fingerprint":"29bd75537467f3f4","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Ce rol au metodele de investigație radiologică în diagnosticul și evaluarea formelor de anodonție?","options":[{"id":"A","text":"Ortopantomograma reprezintă un examen opțional, folosit doar în cazurile în care lipsesc toți dinții de pe o arcadă."},{"id":"B","text":"Ortopantomograma nu poate substitui teleradiografia în evaluarea creșterii și dezvoltării oaselor maxilare."},{"id":"C","text":"Teleradiografia frontală este considerată cea mai utilă dintre incidențele teleradiografice pentru cazurile de anodonție."},{"id":"D","text":"Investigația teleradiografică este complet inutilă pentru monitorizarea și evaluarea eficienței metodelor terapeutice pe parcursul tratamentului."},{"id":"E","text":"Pe baza teleradiografiei se pot evalua posibilitățile de creștere a aparatului dento-maxilar (prognosticul de creștere) în funcție de vârsta și sexul pacientului."}],"correct":["B","C","E"],"pages":[466],"source":"set-2"},{"id":"set2-YD_6Vcvu","fingerprint":"b804e7913b5e4660","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care dintre următoarele afirmații referitoare la păstrarea dinților temporari în cazul anodonției este corectă?","options":[{"id":"A","text":"Dinții frontali temporari prezintă dimensiuni, formă și culoare similare cu corespondenții lor definitivi, justificând păstrarea lor pe termen lung."},{"id":"B","text":"Dinții frontali temporari trebuie menținuți pe arcadă deoarece aceștia pot persista funcțional până la vârsta de 45-50 de ani."},{"id":"C","text":"Conduita terapeutică în anodonțiile reduse ale dinților anteriori cu persistența dinților temporari vizează preponderent terapia conservatoare a acestora."},{"id":"D","text":"Păstrarea dinților temporari este recomandată chiar și în prezența rizalizei, cu condiția absenței leziunilor carioase extinse."},{"id":"E","text":"Al doilea molar temporar poate rămâne pe arcadă, în absența premolarului 2, până la vârsta de 45-50 de ani."}],"correct":["E"],"pages":[467],"source":"set-2"},{"id":"set2-Z8s7OFfD","fingerprint":"da09092783d8dcaf","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"Care sunt obiectivele tratamentului ortodontic de menținere a spațiilor în situația în care acestea nu pot fi închise sau reduse (precum în anodonțiile întinse sau subtotale)?","options":[{"id":"A","text":"Protezarea cu caracter definitiv încă din perioada de creștere activă pentru a oferi echilibru funcțional imediat."},{"id":"B","text":"Asigurarea paralelismului dinților existenți pentru a permite aplicarea unor soluții implanto-protetice ulterioare încheierii proceselor de creștere."},{"id":"C","text":"Stimularea dezvoltării oaselor maxilare și asigurarea unor rapoarte normale între cele două maxilare."},{"id":"D","text":"Extracția dirijată a incisivilor laterali temporari urmată de cea a caninilor temporari pentru a favoriza erupția dinților permanenți."},{"id":"E","text":"Dirijarea erupției dentare și distribuția optimă a dinților pe arcadă."}],"correct":["B","C","E"],"pages":[467],"source":"set-2"},{"id":"set2-PDnpcLs6","fingerprint":"de8a516fd62dfa5f","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Care este motivul principal pentru care deplasările meziale ale dinților în anodonții se realizează mult mai greu și cu o rată mai mică, în ciuda mișcării fiziologice de mezializare?","options":[{"id":"A","text":"Prezența unor factori de creștere în exces la nivelul parodonțiului marginal al dinților restanți."},{"id":"B","text":"Lipsa de suport osos, asociată cu absența fibrelor parodontale transseptale."},{"id":"C","text":"Tendința naturală a aparatului dento-maxilar de a dirija mișcarea dentară exclusiv către distal."},{"id":"D","text":"Ritmul accelerat de creștere a aparatului dento-maxilar care împiedică stabilizarea forțelor ortodontice pe parcursul tratamentului."},{"id":"E","text":"Dimensiunea coronară disproporționată a dinților permanenți comparativ cu omologii lor deciduali."}],"correct":["B"],"pages":[467],"source":"set-2"},{"id":"set2-Xtv32LTL","fingerprint":"0f109d9e9264b515","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CM","text":"În abordarea terapeutică a anodonțiilor totale, obiectivele tratamentului ortodontic includ:","options":[{"id":"A","text":"Aplicarea unor soluții implanto-protetice cu caracter definitiv în jurul vârstei de 12-14 ani."},{"id":"B","text":"Asigurarea cadrului necesar pentru alimentarea optimă a copilului și creșterea eficienței masticatorii."},{"id":"C","text":"Stimularea dezvoltării osoase necesară soluțiilor implanto-protetice sau protetice ulterioare."},{"id":"D","text":"Închiderea completă a spațiilor interdentare exclusiv prin deplasarea corporală a dinților restanți."},{"id":"E","text":"Obținerea unei dimensiuni verticale a etajului interior și a unui profil care să îmbunătățească aspectul fizionomic."}],"correct":["B","C","E"],"pages":[467],"source":"set-2"},{"id":"set2-xamt6RLr","fingerprint":"d931307058a8b687","chapterId":"set-2","subchapterId":"set2-6.1.2","type":"CS","text":"Închiderea spațiilor în anodonțiile frontale reduse prezintă o serie de particularități clinice și terapeutice. Care dintre următoarele afirmații este corectă în acest context?","options":[{"id":"A","text":"Conduita ideală recomandată de Hotz este orientată în favoarea soluției protetice, deoarece aceasta eliberează imediat și permanent pacientul de necesitatea asistenței stomatologice."},{"id":"B","text":"Extracția dirijată se concretizează prin extracția incisivilor laterali superiori temporari, urmată de cea a caninilor superiori temporari pentru a permite evoluția naturală a caninilor definitivi lângă incisivii centrali."},{"id":"C","text":"Extracția dirijată presupune extracția inițială a caninilor superiori temporari, urmată ulterior de cea a incisivilor laterali superiori temporari."},{"id":"D","text":"Aparatele ortodontice utilizate pentru închiderea breșelor trebuie să aibă ca obiectiv principal deplasarea radiculară către distal a structurilor dentare."},{"id":"E","text":"Cu cât extracția dintelui temporar este realizată mai tardiv, cu atât sunt oferite condiții mai favorabile și predictibile pentru migrarea mezială a dinților permanenți."}],"correct":["B"],"pages":[467],"source":"set-2"}];
